"""异常任务 → 运营动作空壳 + 负责人推送 + 逾期升级（编排）。"""

from __future__ import annotations

import logging
from typing import Any

from app.config import Settings, get_settings
from app.notify.owner_push import push_tasks_to_owners
from app.store.db import Database
from app.sync.writer import write_action_shells_to_feishu, write_tasks_to_feishu

logger = logging.getLogger(__name__)


def dispatch_open_tasks(
    db: Database,
    biz_date: str,
    *,
    settings: Settings | None = None,
    push_tasks: bool = True,
    create_action_shells: bool = True,
    notify_owners: bool = True,
    escalate: bool = False,
    dry_run_notify: bool = False,
    only_new_notify: bool = False,
) -> dict[str, Any]:
    """日批后半段：推飞书任务 → 预建动作空壳 → 按负责人通知 → 逾期升级。"""
    settings = settings or get_settings()
    open_tasks = [
        t
        for t in db.list_tasks(biz_date=biz_date)
        if t.get("status") not in ("closed", "resolved")
        and t.get("level") in ("red", "orange")
    ]
    out: dict[str, Any] = {
        "open_tasks": len(open_tasks),
        "feishu_tasks": 0,
        "action_shells": {},
        "owner_push": {},
    }

    if push_tasks and open_tasks:
        try:
            out["feishu_tasks"] = write_tasks_to_feishu(open_tasks, settings=settings)
        except Exception as e:
            logger.exception("推飞书任务失败")
            out["feishu_tasks_error"] = str(e)

    if create_action_shells and open_tasks:
        try:
            out["action_shells"] = write_action_shells_to_feishu(
                open_tasks, settings=settings
            )
        except Exception as e:
            logger.exception("预建动作空壳失败")
            out["action_shells_error"] = str(e)

    if notify_owners:
        try:
            out["owner_push"] = push_tasks_to_owners(
                db,
                biz_date,
                settings=settings,
                dry_run=dry_run_notify,
                only_new=only_new_notify,
            )
        except Exception as e:
            logger.exception("负责人推送失败")
            out["owner_push_error"] = str(e)

    if escalate:
        from app.notify.escalate import send_escalate_notification

        try:
            out["escalate"] = send_escalate_notification(
                db, settings=settings, dry_run=dry_run_notify
            )
        except Exception as e:
            logger.exception("逾期升级通知失败")
            out["escalate_error"] = str(e)

    return out

from __future__ import annotations

import logging
import time
from typing import Any, Iterator

import httpx

from app.config import Settings, get_settings

logger = logging.getLogger(__name__)


class FeishuError(Exception):
    def __init__(self, code: int | str, message: str, payload: Any = None) -> None:
        super().__init__(f"[{code}] {message}")
        self.code = code
        self.message = message
        self.payload = payload


class FeishuClient:
    """飞书开放平台：tenant token + 多维表格 + 自定义机器人 webhook。"""

    BASE = "https://open.feishu.cn/open-apis"

    def __init__(self, settings: Settings | None = None, timeout: float = 60.0) -> None:
        self.settings = settings or get_settings()
        if not self.settings.has_feishu:
            raise FeishuError("config", "缺少 FEISHU_APP_ID / FEISHU_APP_SECRET")
        self._http = httpx.Client(timeout=timeout)
        self._token: str | None = None
        self._token_expire_at: float = 0.0

    def close(self) -> None:
        self._http.close()

    def __enter__(self) -> FeishuClient:
        return self

    def __exit__(self, *args: object) -> None:
        self.close()

    def get_tenant_access_token(self, *, force: bool = False) -> str:
        if not force and self._token and self._token_expire_at - 60 > time.time():
            return self._token
        url = f"{self.BASE}/auth/v3/tenant_access_token/internal"
        resp = self._http.post(
            url,
            json={
                "app_id": self.settings.feishu_app_id,
                "app_secret": self.settings.feishu_app_secret,
            },
        )
        resp.raise_for_status()
        data = resp.json()
        if data.get("code") != 0:
            raise FeishuError(data.get("code"), data.get("msg") or "token failed", data)
        self._token = data["tenant_access_token"]
        self._token_expire_at = time.time() + int(data.get("expire") or 7200)
        return self._token

    def _headers(self) -> dict[str, str]:
        return {
            "Authorization": f"Bearer {self.get_tenant_access_token()}",
            "Content-Type": "application/json; charset=utf-8",
        }

    def _api(
        self,
        method: str,
        path: str,
        *,
        params: dict[str, Any] | None = None,
        json_body: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        url = f"{self.BASE}{path}"
        resp = self._http.request(
            method,
            url,
            headers=self._headers(),
            params=params,
            json=json_body,
        )
        try:
            data = resp.json()
        except Exception:
            resp.raise_for_status()
            raise FeishuError(resp.status_code, resp.text[:500])
        # 飞书业务错误常伴随 HTTP 400，优先解析 body
        if data.get("code") not in (0, None) or not resp.is_success:
            if data.get("code") in (0, None) and not resp.is_success:
                raise FeishuError(resp.status_code, resp.text[:500], data)
            if data.get("code") not in (0, None):
                raise FeishuError(
                    data.get("code"),
                    data.get("msg") or "api error",
                    data,
                )
        return data

    # --- bitable meta ---
    def create_bitable_app(self, name: str, *, folder_token: str | None = None) -> dict[str, Any]:
        """创建多维表格应用，返回 app 信息（含 app_token）。"""
        body: dict[str, Any] = {"name": name}
        if folder_token:
            body["folder_token"] = folder_token
        data = self._api("POST", "/bitable/v1/apps", json_body=body)
        return data.get("data") or {}

    def list_tables(self, app_token: str) -> list[dict[str, Any]]:
        data = self._api("GET", f"/bitable/v1/apps/{app_token}/tables")
        items = (data.get("data") or {}).get("items") or []
        return items

    def create_table(
        self,
        app_token: str,
        name: str,
        fields: list[dict[str, Any]],
    ) -> dict[str, Any]:
        """fields 例: [{"field_name":"日期","type":5}, ...]  type 见飞书文档。"""
        body = {"table": {"name": name, "default_view_name": "默认视图", "fields": fields}}
        data = self._api(
            "POST",
            f"/bitable/v1/apps/{app_token}/tables",
            json_body=body,
        )
        return data.get("data") or {}

    def list_fields(self, app_token: str, table_id: str) -> list[dict[str, Any]]:
        data = self._api(
            "GET",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/fields",
        )
        return (data.get("data") or {}).get("items") or []

    def create_field(
        self,
        app_token: str,
        table_id: str,
        field_name: str,
        field_type: int,
        *,
        property_: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        body: dict[str, Any] = {"field_name": field_name, "type": field_type}
        if property_:
            body["property"] = property_
        data = self._api(
            "POST",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/fields",
            json_body=body,
        )
        return data.get("data") or {}

    # --- views ---
    def list_views(self, app_token: str, table_id: str) -> list[dict[str, Any]]:
        data = self._api("GET", f"/bitable/v1/apps/{app_token}/tables/{table_id}/views")
        return (data.get("data") or {}).get("items") or []

    def create_view(
        self,
        app_token: str,
        table_id: str,
        view_name: str,
        *,
        view_type: str = "grid",
    ) -> dict[str, Any]:
        data = self._api(
            "POST",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/views",
            json_body={"view_name": view_name, "view_type": view_type},
        )
        return (data.get("data") or {}).get("view") or data.get("data") or {}

    def patch_view(
        self,
        app_token: str,
        table_id: str,
        view_id: str,
        body: dict[str, Any],
    ) -> dict[str, Any]:
        data = self._api(
            "PATCH",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/views/{view_id}",
            json_body=body,
        )
        return data.get("data") or {}

    def patch_view_filter(
        self,
        app_token: str,
        table_id: str,
        view_id: str,
        *,
        field_id: str,
        operator: str,
        value: str,
        conjunction: str = "and",
    ) -> dict[str, Any]:
        """设置单条件筛选。value 格式因字段类型而异，常见为 JSON 数组字符串如 '["特米-UK"]'。"""
        body = {
            "property": {
                "filter_info": {
                    "conjunction": conjunction,
                    "conditions": [
                        {
                            "field_id": field_id,
                            "operator": operator,
                            "value": value,
                        }
                    ],
                }
            }
        }
        return self.patch_view(app_token, table_id, view_id, body)

    def field_id_map(self, app_token: str, table_id: str) -> dict[str, str]:
        return {
            f.get("field_name"): f.get("field_id")
            for f in self.list_fields(app_token, table_id)
            if f.get("field_name") and f.get("field_id")
        }

    # --- records ---
    def bitable_list_records(
        self,
        app_token: str,
        table_id: str,
        *,
        page_size: int = 100,
        page_token: str | None = None,
        filter_expr: str | None = None,
    ) -> dict[str, Any]:
        params: dict[str, Any] = {"page_size": page_size}
        if page_token:
            params["page_token"] = page_token
        if filter_expr:
            params["filter"] = filter_expr
        data = self._api(
            "GET",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/records",
            params=params,
        )
        return data.get("data") or {}

    def iter_records(
        self,
        app_token: str,
        table_id: str,
        *,
        page_size: int = 100,
        filter_expr: str | None = None,
    ) -> Iterator[dict[str, Any]]:
        page_token = None
        while True:
            data = self.bitable_list_records(
                app_token,
                table_id,
                page_size=page_size,
                page_token=page_token,
                filter_expr=filter_expr,
            )
            for item in data.get("items") or []:
                yield item
            if not data.get("has_more"):
                break
            page_token = data.get("page_token")
            if not page_token:
                break

    def bitable_batch_create(
        self,
        app_token: str,
        table_id: str,
        records: list[dict[str, Any]],
    ) -> dict[str, Any]:
        data = self._api(
            "POST",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/records/batch_create",
            json_body={"records": records},
        )
        return data.get("data") or {}

    def bitable_batch_update(
        self,
        app_token: str,
        table_id: str,
        records: list[dict[str, Any]],
    ) -> dict[str, Any]:
        data = self._api(
            "POST",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/records/batch_update",
            json_body={"records": records},
        )
        return data.get("data") or {}

    def upsert_by_text_key(
        self,
        app_token: str,
        table_id: str,
        records_fields: list[dict[str, Any]],
        *,
        key_field: str = "主键",
        batch_size: int = 100,
    ) -> dict[str, int]:
        """按文本主键幂等写入：已存在则 update，否则 create。

        records_fields: 每项为 fields 字典（必须含 key_field）。
        """
        existing: dict[str, str] = {}
        for item in self.iter_records(app_token, table_id, page_size=100):
            fields = item.get("fields") or {}
            key = fields.get(key_field)
            rid = item.get("record_id")
            if key is not None and rid:
                existing[str(key)] = rid

        to_create: list[dict[str, Any]] = []
        to_update: list[dict[str, Any]] = []
        for fields in records_fields:
            key = fields.get(key_field)
            if key is None:
                continue
            key_s = str(key)
            if key_s in existing:
                to_update.append({"record_id": existing[key_s], "fields": fields})
            else:
                to_create.append({"fields": fields})

        created = updated = 0
        for i in range(0, len(to_create), batch_size):
            chunk = to_create[i : i + batch_size]
            self.bitable_batch_create(app_token, table_id, chunk)
            created += len(chunk)
            time.sleep(0.2)
        for i in range(0, len(to_update), batch_size):
            chunk = to_update[i : i + batch_size]
            self.bitable_batch_update(app_token, table_id, chunk)
            updated += len(chunk)
            time.sleep(0.2)

        logger.info(
            "Feishu upsert table=%s create=%s update=%s", table_id, created, updated
        )
        return {"created": created, "updated": updated, "total": created + updated}

    def _post_webhook(self, body: dict[str, Any], webhook: str | None = None) -> dict[str, Any]:
        """发送 webhook 消息的底层方法，返回响应 data。"""
        url = webhook or self.settings.feishu_bot_webhook
        if not url:
            logger.warning("FEISHU_BOT_WEBHOOK 未配置，跳过消息")
            return {}
        resp = self._http.post(url, json=body)
        resp.raise_for_status()
        data = resp.json() if resp.content else {}
        if data.get("code") not in (None, 0) and data.get("StatusCode") not in (
            None,
            0,
        ):
            raise FeishuError(
                data.get("code") or data.get("StatusCode"), str(data), data
            )
        return data

    def send_webhook_text(self, text: str, webhook: str | None = None) -> None:
        self._post_webhook({"msg_type": "text", "content": {"text": text}}, webhook=webhook)

    def send_webhook_text_with_at(
        self,
        text: str,
        *,
        at_open_ids: list[str] | None = None,
        webhook: str | None = None,
    ) -> None:
        """群自定义机器人文本；text 内可含 <at user_id=\"ou_xxx\"></at> 实现 @。"""
        body_text = text
        if at_open_ids:
            tags = "".join(f'<at user_id="{oid}"></at>' for oid in at_open_ids if oid)
            if tags and tags not in body_text:
                body_text = f"{tags}\n{body_text}"
        self.send_webhook_text(body_text, webhook=webhook)

    def send_webhook_card(self, card: dict[str, Any], webhook: str | None = None) -> dict[str, Any]:
        """发送飞书交互式卡片消息（msg_type: interactive）。"""
        body: dict[str, Any] = {"msg_type": "interactive", "card": card}
        return self._post_webhook(body, webhook=webhook)

    def create_records_if_absent(
        self,
        app_token: str,
        table_id: str,
        records_fields: list[dict[str, Any]],
        *,
        key_field: str = "主键",
        batch_size: int = 100,
    ) -> dict[str, int]:
        """仅创建尚不存在主键的记录；已存在则跳过（永不 update，保护人工填写）。"""
        existing: set[str] = set()
        for item in self.iter_records(app_token, table_id, page_size=100):
            fields = item.get("fields") or {}
            key = fields.get(key_field)
            if key is not None:
                existing.add(str(key))

        to_create: list[dict[str, Any]] = []
        for fields in records_fields:
            key = fields.get(key_field)
            if key is None:
                continue
            if str(key) in existing:
                continue
            to_create.append({"fields": fields})

        created = 0
        for i in range(0, len(to_create), batch_size):
            chunk = to_create[i : i + batch_size]
            self.bitable_batch_create(app_token, table_id, chunk)
            created += len(chunk)
            time.sleep(0.2)

        skipped = len(records_fields) - created
        logger.info(
            "Feishu create-if-absent table=%s create=%s skip=%s",
            table_id,
            created,
            skipped,
        )
        return {
            "created": created,
            "skipped": skipped,
            "total": len(records_fields),
        }

    def ensure_text_fields(
        self,
        app_token: str,
        table_id: str,
        field_names: list[str],
        *,
        field_type: int = 1,
    ) -> list[str]:
        """确保文本字段存在，返回新建的字段名列表。"""
        existing = {
            f.get("field_name")
            for f in self.list_fields(app_token, table_id)
            if f.get("field_name")
        }
        created: list[str] = []
        for name in field_names:
            if name in existing:
                continue
            self.create_field(app_token, table_id, name, field_type)
            created.append(name)
            existing.add(name)
            time.sleep(0.15)
        return created


# ---------------------------------------------------------------------------
# 交互式卡片构建辅助（纯函数，不依赖 FeishuClient）
# ---------------------------------------------------------------------------

# 飞书卡片 header 颜色：red | blue | green | orange | yellow | purple | grey
_CARD_COLORS: dict[str, str] = {
    "red": "red",
    "orange": "orange",
    "yellow": "yellow",
    "green": "green",
    "blue": "blue",
    "purple": "purple",
    "grey": "grey",
}


def card_header(title: str, color: str = "blue") -> dict[str, Any]:
    """构建卡片头部。color: red/orange/yellow/green/blue/purple/grey。"""
    return {
        "header": {
            "title": {"tag": "plain_text", "content": title},
            "template": _CARD_COLORS.get(color, "blue"),
        }
    }


def card_md(content: str) -> dict[str, Any]:
    """构建 lark_md 文本块元素。"""
    return {"tag": "div", "text": {"tag": "lark_md", "content": content}}


def card_hr() -> dict[str, Any]:
    """构建分割线元素。"""
    return {"tag": "hr"}


def card_button(text: str, url: str, *, primary: bool = False) -> dict[str, Any]:
    """构建跳转按钮。primary=True 时为主要按钮样式。"""
    btn: dict[str, Any] = {
        "tag": "button",
        "text": {"tag": "plain_text", "content": text},
        "url": url,
    }
    if primary:
        btn["type"] = "primary"
    return btn


def card_action(*buttons: dict[str, Any]) -> dict[str, Any]:
    """构建按钮行元素。"""
    return {"tag": "action", "actions": list(buttons)}


def card_note(content: str) -> dict[str, Any]:
    """构建 note 元素（提示文字）。"""
    return {"tag": "note", "elements": [{"tag": "plain_text", "content": content}]}


def build_level_color(level: str) -> str:
    """red→red, orange→orange, yellow→yellow，其余用 blue。"""
    return level if level in _CARD_COLORS else "blue"


def build_level_icon(level: str) -> str:
    """异常等级 → emoji 前缀。"""
    return {"red": "🔴", "orange": "🟠", "yellow": "🟡"}.get(level, "🔵")

from __future__ import annotations

import os
from functools import lru_cache
from pathlib import Path
from typing import Any

import yaml
from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict

ROOT_DIR = Path(__file__).resolve().parent.parent
DEFAULT_CONFIG_PATH = ROOT_DIR / "config" / "config.yaml"
EXAMPLE_CONFIG_PATH = ROOT_DIR / "config" / "config.example.yaml"
DEFAULT_RULES_PATH = ROOT_DIR / "config" / "rules.default.yaml"


class Settings(BaseSettings):
    model_config = SettingsConfigDict(
        env_file=str(ROOT_DIR / ".env"),
        env_file_encoding="utf-8",
        extra="ignore",
    )

    sellfox_client_id: str = Field(default="", alias="SELLFOX_CLIENT_ID")
    sellfox_client_secret: str = Field(default="", alias="SELLFOX_CLIENT_SECRET")
    sellfox_base_url: str = Field(
        default="https://openapi.sellfox.com", alias="SELLFOX_BASE_URL"
    )

    feishu_app_id: str = Field(default="", alias="FEISHU_APP_ID")
    feishu_app_secret: str = Field(default="", alias="FEISHU_APP_SECRET")
    feishu_bitable_app_token: str = Field(default="", alias="FEISHU_BITABLE_APP_TOKEN")
    feishu_table_asin_daily: str = Field(default="", alias="FEISHU_TABLE_ASIN_DAILY")
    feishu_table_tasks: str = Field(default="", alias="FEISHU_TABLE_TASKS")
    feishu_table_actions: str = Field(default="", alias="FEISHU_TABLE_ACTIONS")
    feishu_table_config: str = Field(default="", alias="FEISHU_TABLE_CONFIG")
    feishu_table_daily_summary: str = Field(default="", alias="FEISHU_TABLE_DAILY_SUMMARY")
    feishu_bot_webhook: str = Field(default="", alias="FEISHU_BOT_WEBHOOK")

    data_dir: Path = Field(default=ROOT_DIR / "data", alias="DATA_DIR")
    log_level: str = Field(default="INFO", alias="LOG_LEVEL")

    @property
    def db_path(self) -> Path:
        return Path(self.data_dir) / "bridge.db"

    @property
    def has_sellfox(self) -> bool:
        return bool(self.sellfox_client_id and self.sellfox_client_secret)

    @property
    def has_feishu(self) -> bool:
        return bool(self.feishu_app_id and self.feishu_app_secret)


def load_yaml(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    with path.open("r", encoding="utf-8") as f:
        data = yaml.safe_load(f) or {}
    if not isinstance(data, dict):
        raise ValueError(f"YAML root must be mapping: {path}")
    return data


@lru_cache
def get_settings() -> Settings:
    return Settings()


def get_app_config() -> dict[str, Any]:
    """Merge example defaults with optional config.yaml."""
    base = load_yaml(EXAMPLE_CONFIG_PATH)
    override = load_yaml(DEFAULT_CONFIG_PATH)
    return _deep_merge(base, override)


def get_rules_config() -> dict[str, Any]:
    return load_yaml(DEFAULT_RULES_PATH)


def _deep_merge(a: dict[str, Any], b: dict[str, Any]) -> dict[str, Any]:
    out = dict(a)
    for k, v in b.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = _deep_merge(out[k], v)
        else:
            out[k] = v
    return out


def ensure_data_dir(settings: Settings | None = None) -> Path:
    s = settings or get_settings()
    path = Path(s.data_dir)
    path.mkdir(parents=True, exist_ok=True)
    (path / "snapshots").mkdir(parents=True, exist_ok=True)
    return path

#!/usr/bin/env python
"""飞书多维表格字段类型迁移：文本日期 → 原生日期类型。

飞书 API 不支持修改已有字段类型，因此迁移策略为：
  1. 为每张表创建新的 DATE 类型字段（如 日期_date, 截止时间_date）
  2. 将旧文本字段的值转换为毫秒时间戳写入新字段
  3. 完成后需手动在飞书 UI 中：删旧字段 → 重命名新字段（去掉 _date 后缀）

用法:
  python scripts/migrate_feishu_fields.py          # 全部表迁移
  python scripts/migrate_feishu_fields.py --dry-run  # 仅检测，不创建/写入
  python scripts/migrate_feishu_fields.py --table 异常任务  # 只迁移指定表
"""

from __future__ import annotations

import argparse
import logging
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from app.clients.feishu import FeishuClient
from app.config import get_settings

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("migrate_feishu_fields")

# 需要迁移的字段列表（表名 → 旧文本字段名 → 新 DATE 字段名）
MIGRATIONS: dict[str, dict[str, str]] = {
    "ASIN每日数据": {
        "日期": "日期",
    },
    "异常任务": {
        "日期": "日期",
        "截止时间": "截止时间",
    },
    "运营动作记录": {
        "执行日期": "执行日期",
        "复查日期": "复查日期",
    },
}

# 动作表的等级字段从文本改单选
SINGLE_MIGRATIONS: dict[str, dict[str, list[str]]] = {
    "运营动作记录": {
        "等级": ["yellow", "orange", "red"],
    },
}


def parse_date_to_ts(text: str | None) -> int | None:
    """将文本日期转为毫秒 Unix 时间戳。"""
    if not text:
        return None
    text = str(text).strip()
    for fmt in ("%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            dt = datetime.strptime(text, fmt)
            return int(dt.replace(tzinfo=timezone.utc).timestamp() * 1000)
        except ValueError:
            continue
    logger.warning("无法解析日期: %s", text)
    return None


def migrate_table(
    client: FeishuClient,
    app_token: str,
    table_id: str,
    table_name: str,
    field_map: dict[str, str],
    *,
    dry_run: bool = False,
) -> dict[str, int]:
    """为一张表的文本日期字段创建对应的 DATE 字段并迁移数据。"""
    logger.info("=== 处理表: %s (%s) ===", table_name, table_id)

    # 获取现有字段
    all_fields = client.list_fields(app_token, table_id)
    field_name_to_id = {f.get("field_name"): f.get("field_id") for f in all_fields}
    field_name_to_type = {f.get("field_name"): f.get("type") for f in all_fields}

    result: dict[str, int] = {"created_fields": 0, "migrated_records": 0}

    for old_name, new_name in sorted(field_map.items()):
        if old_name not in field_name_to_id:
            logger.info("  字段 [%s] 不存在，跳过", old_name)
            continue

        old_type = field_name_to_type.get(old_name)
        logger.info(
            "  字段 [%s] type=%s → 目标 DATE (5)",
            old_name,
            old_type,
        )

        if old_type == 5:
            logger.info("    已是 DATE 类型，跳过")
            continue

        # 检查是否已有同名 DATE 字段
        if new_name in field_name_to_id:
            existing_new_type = field_name_to_type.get(new_name)
            if existing_new_type == 5:
                logger.info("    目标字段 [%s] 已存在且为 DATE 类型", new_name)
            else:
                logger.warning(
                    "    目标字段 [%s] 已存在但 type=%s，非 DATE",
                    new_name,
                    existing_new_type,
                )
        else:
            if not dry_run:
                try:
                    client.create_field(app_token, table_id, new_name, 5)
                    logger.info("    ✅ 创建 DATE 字段 [%s]", new_name)
                    result["created_fields"] += 1
                except Exception as e:
                    logger.error("    ❌ 创建字段失败: %s", e)
                    continue
            else:
                logger.info("    [DRY-RUN] 将创建 DATE 字段 [%s]", new_name)
                result["created_fields"] += 1

        # 迁移数据
        old_field_id = field_name_to_id[old_name]
        total = 0
        batch: list[dict[str, Any]] = []
        for item in client.iter_records(app_token, table_id, page_size=100):
            rid = item.get("record_id")
            fields = item.get("fields") or {}
            old_val = fields.get(old_name)
            if old_val is None:
                continue
            ts = parse_date_to_ts(old_val)
            if ts is None:
                continue
            batch.append({"record_id": rid, "fields": {new_name: ts}})
            total += 1
            if len(batch) >= 100:
                if not dry_run:
                    client.bitable_batch_update(app_token, table_id, batch)
                batch = []

        if batch:
            if not dry_run:
                client.bitable_batch_update(app_token, table_id, batch)

        action = "将写入" if dry_run else "已写入"
        logger.info("    %s %s 条记录到 [%s]", action, total, new_name)
        result["migrated_records"] += total

    return result


def migrate_single_select(
    client: FeishuClient,
    app_token: str,
    table_id: str,
    table_name: str,
    field_map: dict[str, list[str]],
    *,
    dry_run: bool = False,
) -> dict[str, int]:
    """为文本字段创建单选版本并迁移数据。"""
    logger.info("=== 单选迁移: %s ===", table_name)

    all_fields = client.list_fields(app_token, table_id)
    field_name_to_type = {f.get("field_name"): f.get("type") for f in all_fields}

    result: dict[str, int] = {"created_fields": 0, "migrated_records": 0}

    for field_name, options in field_map.items():
        old_type = field_name_to_type.get(field_name)
        logger.info("  字段 [%s] type=%s → 目标 SINGLE(3)", field_name, old_type)

        if old_type == 3:
            logger.info("    已是单选类型，跳过")
            continue

        new_name = field_name  # 同名替换（旧字段需手动删除）

        # 实际需要先建新字段（不同名），再搬数据
        tmp_name = f"{field_name}_单选"
        all_names = {f.get("field_name") for f in all_fields}
        if tmp_name not in all_names:
            if not dry_run:
                client.create_field(
                    app_token,
                    table_id,
                    tmp_name,
                    3,
                    property_={"options": [{"name": o} for o in options]},
                )
                logger.info("    ✅ 创建单选字段 [%s]", tmp_name)
                result["created_fields"] += 1
            else:
                logger.info("    [DRY-RUN] 将创建单选字段 [%s]", tmp_name)
                result["created_fields"] += 1

        # 搬数据
        old_field_id = next(
            (f.get("field_id") for f in all_fields if f.get("field_name") == field_name),
            None,
        )
        if not old_field_id:
            continue

        total = 0
        batch = []
        for item in client.iter_records(app_token, table_id, page_size=100):
            rid = item.get("record_id")
            fields = item.get("fields") or {}
            old_val = fields.get(field_name)
            if old_val is None:
                continue
            batch.append({"record_id": rid, "fields": {tmp_name: str(old_val)}})
            total += 1
            if len(batch) >= 100:
                if not dry_run:
                    client.bitable_batch_update(app_token, table_id, batch)
                batch = []
        if batch and not dry_run:
            client.bitable_batch_update(app_token, table_id, batch)

        logger.info("    已处理 %s 条记录到 [%s]", total, tmp_name)
        result["migrated_records"] += total

    return result


def main() -> None:
    parser = argparse.ArgumentParser(description="飞书字段类型迁移")
    parser.add_argument("--dry-run", action="store_true", help="只检测不写入")
    parser.add_argument("--table", help="只迁移指定表名")
    args = parser.parse_args()

    settings = get_settings()
    if not settings.has_feishu:
        logger.error("缺少飞书凭证 (FEISHU_APP_ID / FEISHU_APP_SECRET)")
        sys.exit(1)

    app_token = settings.feishu_bitable_app_token
    if not app_token:
        logger.error("缺少 FEISHU_BITABLE_APP_TOKEN")
        sys.exit(1)

    # 表名 → table_id 映射
    name_to_id: dict[str, str] = {
        "ASIN每日数据": settings.feishu_table_asin_daily,
        "异常任务": settings.feishu_table_tasks,
        "运营动作记录": settings.feishu_table_actions,
    }

    with FeishuClient(settings) as client:
        # 日期字段迁移
        for table_name, field_map in MIGRATIONS.items():
            if args.table and args.table != table_name:
                continue
            table_id = name_to_id.get(table_name, "")
            if not table_id:
                logger.warning("表 [%s] 未配置 table_id，跳过", table_name)
                continue
            try:
                r = migrate_table(
                    client, app_token, table_id, table_name, field_map, dry_run=args.dry_run
                )
                logger.info("  → 新建字段 %s 个，迁移记录 %s 条", r["created_fields"], r["migrated_records"])
            except Exception as e:
                logger.exception("迁移表 [%s] 失败", table_name)

        # 单选字段迁移
        for table_name, field_map in SINGLE_MIGRATIONS.items():
            if args.table and args.table != table_name:
                continue
            table_id = name_to_id.get(table_name, "")
            if not table_id:
                continue
            try:
                r = migrate_single_select(
                    client, app_token, table_id, table_name, field_map, dry_run=args.dry_run
                )
                logger.info("  → 新建单选字段 %s 个，迁移记录 %s 条", r["created_fields"], r["migrated_records"])
            except Exception as e:
                logger.exception("单选迁移 [%s] 失败", table_name)

    print("\n" + "=" * 60)
    print("⚠️  手动步骤（飞书 UI 中完成）：")
    print("1. 删除旧的文本类型字段（如: 日期, 截止时间 等）")
    print("2. 将新字段重命名，去掉临时后缀: 日期_date → 日期")
    print("3. 对于单选迁移: 删除旧文本等级字段，将 等级_单选 重命名为 等级")
    print("=" * 60)


if __name__ == "__main__":
    main()

